170	  private async findGridCellBounds(col: number, row: number, nthChild = 0) {
171	    return this.gridCanvas.nth(nthChild).evaluate(
172	      (node, { col, row }) => {
173	        const fiberKey = Object.keys(node).find(x => x && x.includes("__reactFiber"));
174	
175	        if (!fiberKey || !node.parentNode) return null;
176	
177	        /*
178	        We seek over the fiber node (hack), ignore typings for it.
179	      */
180	        const fiberParent = node.parentNode[fiberKey as keyof typeof node.parentNode] as any;
181	
182	        const bounds: { x: number; y: number; width: number; height: number } =
183	          fiberParent.pendingProps.children.props.gridRef.current.getBounds(col, row);
184	
185	        if (!bounds) return null;
186	
187	        return {
188	          ...bounds,
189	          center: {
190	            x: bounds.x + bounds.width / 2,
191	            y: bounds.y + bounds.height / 2,
192	          },
193	        };
194	      },
195	      { col, row },
196	    );
197	  }
